/** Пополнува полиња што може да недостасуваат во рачно менуван сејв. */
function normalizirajRastenie(r){
  return {
    sorta: r.sorta,
    faza: FAZI[r.faza] ? r.faza : "NIKNENJE",
    vozrast: Number.isFinite(r.vozrast) ? r.vozrast : 0,
    voda:    Number.isFinite(r.voda)    ? stegni(r.voda, 0, 100)    : 70,
    hraniva: Number.isFinite(r.hraniva) ? stegni(r.hraniva, 0, 100) : 70,
    zdravje: Number.isFinite(r.zdravje) ? stegni(r.zdravje, 0, 100) : 100,
    stetnik: najdiNastan(r.stetnik) ? r.stetnik : null,
    zbirZdravje: Number.isFinite(r.zbirZdravje) ? r.zbirZdravje : 0,
    brojTikovi:  Number.isFinite(r.brojTikovi)  ? r.brojTikovi  : 0,
    deoviSoStetnik: Number.isFinite(r.deoviSoStetnik) ? r.deoviSoStetnik : 0,
    predupredenoPrezrelost: !!r.predupredenoPrezrelost
  };
}

function vchitaj(){
  let surovo;
  try{ surovo = localStorage.getItem(KONFIG.KLUC_SEJV); }
  catch(e){ return false; }                 // localStorage целосно недостапен
  if (!surovo) return false;

  let paket;
  try{ paket = JSON.parse(surovo); }
  catch(e){ izvesti(TEKST.vcitajGreska, "greska"); return false; }

  const s = paket && paket.s;
  if (!s || typeof s !== "object"){ izvesti(TEKST.vcitajGreska, "greska"); return false; }
  if (s.verzija !== KONFIG.VERZIJA){ izvesti(TEKST.starVerzija, "greska"); return false; }

  const svez = novaIgra();
  // Прифаќај само познати полиња; сè друго паѓа назад на почетна вредност.
  sostojba = Object.assign(svez, {
    parichnik: Number.isFinite(s.parichnik) ? Math.max(0, s.parichnik) : svez.parichnik,
    nivo:      Number.isFinite(s.nivo) && s.nivo >= 1 ? Math.floor(s.nivo) : 1,
    iskustvo:  Number.isFinite(s.iskustvo) && s.iskustvo >= 0 ? s.iskustvo : 0,
    den:       Number.isFinite(s.den) && s.den >= 1 ? Math.floor(s.den) : 1,
    chas:      Number.isFinite(s.chas) ? stegni(s.chas, 0, 23) : 6,
    brojLei:   stegni(Math.floor(Number(s.brojLei)) || KONFIG.POCETNI_LEI,
                      KONFIG.POCETNI_LEI, KONFIG.MAX_LEI),
    lampa:     stegni(Math.floor(Number(s.lampa)) || 0, 0, LAMPI.length - 1),
    statistika: Object.assign(svez.statistika, s.statistika || {})
  });

  // Леи — отфрли растенија со непозната сорта, дополни им полињата што фалат
  if (Array.isArray(s.lei)){
    for (let i = 0; i < KONFIG.MAX_LEI; i++){
      const r = s.lei[i] && s.lei[i].rastenie;
      sostojba.lei[i].rastenie = (r && najdiSorta(r.sorta)) ? normalizirajRastenie(r) : null;
    }
  }

  // Семки, сушара, магацин, пазар — филтрирај непознати ид-ја и неброеви,
  // за оштетен сејв да не внесе NaN во парите.
  sostojba.semki = {};
    ...sostojba.magacin.map(x => Number(x.id) || 0));
  sledenId = Math.max(Number(paket.sledenId) || 1, maxId + 1);
  return true;
}

